import sys
from rich.console import Console
from rich.traceback import Traceback

class BadGroup(ExceptionGroup):
    @property
    def exceptions(self):
        return [self]

try:
    raise BadGroup("circular", [BadGroup("circular", [])])
except Exception as e:
    try:
        console = Console(record=True)
        # This should not recurse infinitely now
        console.print_exception()
        print("Success!")
    except RecursionError:
        print("Failed: RecursionError")
        sys.exit(1)
    except Exception as ex:
        print(f"Failed: {ex}")
        sys.exit(1)

